def e(s): return html.escape(s,quote=False)
import base64,subprocess,tempfile
_TH={}
def thumb(name):
    if name in _TH: return _TH[name]
    src=os.path.join('assets',name)
    out=os.path.join(tempfile.gettempdir(),'th_'+name.rsplit('.',1)[0].replace('/','_')+'.jpg')
    if not os.path.exists(out):
        w=subprocess.run(['sips','-g','pixelWidth',src],capture_output=True,text=True).stdout.strip().split()[-1]
        args=['sips','-s','format','jpeg','-s','formatOptions','72']
        if int(w)>1400: args+=['--resampleWidth','1400']
        subprocess.run(args+[src,'--out',out],capture_output=True)
    with open(out,'rb') as f: uri='data:image/jpeg;base64,'+base64.b64encode(f.read()).decode()
    _TH[name]=uri; return uri
def tall(name,alt,cls='tall'):
    return f'<a class="{cls}" href="assets/{name}" target="_blank" title="클릭하면 원본 해상도로 봅니다"><img src="{thumb(name)}" alt="{e(alt)}"></a>'

def page(title,meta,intro,body):
    return f'<!DOCTYPE html>\n<html lang="ko"><head><meta charset="UTF-8"><title>{e(title)}</title><style>{CSS}</style></head><body><div class="c"><h1>{e(title)}</h1><p class="meta">{meta}</p>{intro}{body}</div></body></html>\n'
def table(head,rows):
    t='<table><tr>'+''.join(f'<th>{e(h)}</th>' for h in head)+'</tr>'
    for r in rows: t+='<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>'
    return t+'</table>'
def ba(b,a,cb='이전',ca='이후'):
    return f'<div class="ba"><figure>{tall(b,cb)}<figcaption>{cb} · 클릭하면 원본</figcaption></figure><figure>{tall(a,ca)}<figcaption>{ca} · 클릭하면 원본</figcaption></figure></div>'
def fig(n,c): return f'<figure>{tall(n,c)}<figcaption>{c} · 클릭하면 원본</figcaption></figure>'
def img(n,alt): return f'<figure>{tall(n,alt)}<figcaption>{e(alt)} · 클릭하면 원본</figcaption></figure>'
C=lambda s: f'<code>{e(s)}</code>'

